    String logPattern = "${applicationName}.${logCategory}.${logPriority}. ${message}";
    String logCategory = event.getCategoryName();
    String logPriority = getPriorityString(event.getLevel());

    int priorityIndex = logPattern.indexOf("${logPriority}");
    if (priorityIndex != -1) {
        formattedMessage.insert(priorityIndex, logPriority);
    }

    int categoryIndex = logPattern.indexOf("${logCategory}");
    if (categoryIndex != -1) {
        formattedMessage.insert(categoryIndex, logCategory);
    }

    int applicationNameIndex = logPattern.indexOf("${applicationName}");
    if (applicationNameIndex != -1) {
        formattedMessage.insert(applicationNameIndex, event.getApplicationName());
    }

    return formattedMessage.toString();
}

