    if (b == null) {
        throw new IllegalArgumentException("Input byte array must not be null");
    }

    if (b.length > DEFAULT_BUFFER_SIZE) {
        throw new IllegalArgumentException("Input byte array length exceeding default buffer size");

    int written = 0;
    while (written < b.length) {
        written += write(b, written, Math.min(b.length - written, DEFAULT_BUFFER_SIZE));
    }
}

