private<V, E> void generateBipartiteGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Check if target graph is not created
    if (target == null) {
        throw new IllegalArgumentException("Target graph cannot be null");
    }

    // Check if resultMap is not null
    if (resultMap == null) {
        throw new IllegalArgumentException("Result map cannot be null");
    }

    // Create a bag to hold each type of vertex
    Bag<V> vertexVertices = Bag.of();
    Bag<V> vertexArms = Bag.of();

    // Iterate through the resultMap and populate the corresponding bag
    resultMap.forEach((key, value) -> {
        if (key.equals("Vertices")) {
            vertexVertices.add(value);
        } else if (key.equals("Arms")) {
            vertexArms.add(value);
        }
    });

    // Generate the bipartite graph
    int vertexCount = vertexVertices.size();
    int armCount = vertexArms.size();
    List<V> vertices = new ArrayList<>(vertexCount);
    List<V> arms = new ArrayList<>(armCount);

    // Add vertices to the graph
    for (int i = 0; i < vertexCount; i++) {
        vertices.add(vertexVertices.get(i));
    }

    // Add arms to the graph
    for (int i = 0; i < armCount; i++) {
        arms.add(vertexArms.get(i));
    }

    // Add edges between vertices and arms
    for (V vertex : vertices) {
        for (V arm : arms) {
            target.addEdge(vertex, arm);
        }
    }
}

