    for (V v : resultMap.values()) {
        if (v instanceof LeftVertex) {
            leftSize++;
        } else if (v instanceof RightVertex) {
            rightSize++;
        }
    }

    // Create a complete bipartite graph
    for (int i = 0; i < leftSize; i++) {
        for (int j = 0; j < rightSize; j++) {
            V leftVertex = resultMap.get("LeftVertex" + i);
            V rightVertex = resultMap.get("RightVertex" + j);
