private void generateCompleteBipartiteGraph(Graph<V,E> target, Map<String, V> resultMap) {
    // Check if the target graph is null
    if (target == null) {
        throw new IllegalArgumentException("Target graph cannot be null.");
    }

    // Check if the result map is null or if it is empty
    if (resultMap == null || resultMap.isEmpty()) {
        throw new IllegalArgumentException("Result map cannot be null or empty.");
    }

    // Get the number of vertices in the graph
    int n = resultMap.size();

    // Create two sets of vertices
    Set<V> set1 = new HashSet<>();
    Set<V> set2 = new HashSet<>();

    // Generate vertices for set1 and set2
    for (V vertex : resultMap.values()) {
        set1.add(vertex);
        set2.add(vertex);
    }

    // Check if the number of vertices is odd
    if (n % 2 != 0) {
        throw new IllegalArgumentException("Graph must have an even number of vertices.");
    }

    // Add edges between vertices from set1 and set2
    for (V vertex1 : set1) {
        V vertex2 = set2.stream().findFirst().orElse(null);
        if (vertex2 != null) {
            target.addEdge(vertex1, vertex2);
        }
    }

    // Count the number of edges
    int numEdges = target.edgeSet().size();

    // Check if the number of edges is correct
    if (numEdges != n / 2) {
        throw new IllegalStateException("Number of edges is incorrect.");
    }
}

