public static <T>int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Calculate the length headers to prepend to the message
    int length = 4 + schema.getLengthInBytes(message);
    // Write out the length of the message
    out.write((byte) (length >> 24));
    out.write((byte) (length >> 16));
    out.write((byte) (length >> 8));
    out.write((byte) length);
    // Write out the serialized message
    schema.serializeInto(buffer, message);
    // Return the total size of the message including the header
    return length + buffer.size();
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int messageLength = schema.calculateMessageSize(message);
    out.writeInt(messageLength); // Write the length of the message as an integer
    buffer.put(message); // Write the actual message
    out.flush(); // Flush the OutputStream so it can be written to disk or network
    return messageLength; // Return the size of the message written to the OutputStream
}

