public void insertBefore(Bucket bucket) {
    // Handle null input
    if (bucket == null) {
        throw new IllegalArgumentException("Bucket cannot be null");
    }

    // Check if the bucket is already before the end of the list
    if (this.list.size() == 0 || this.list.get(this.list.size() - 1) == bucket) {
        return;
    }

    // Find the index of the bucket before the target bucket
    int index = this.list.indexOf(bucket);
    if (index == -1) {
        throw new IllegalArgumentException("Bucket not found in the list");
    }

    // Move all elements after the target bucket one position to the right
    List<Bucket> temp = new ArrayList<>(this.list);
    for (int i = index + 1; i < temp.size(); i++) {
        temp.set(i - 1, temp.get(i));
    }

    // Insert the target bucket at the new index
    this.list.add(index, bucket);

    // Create a new list with the updated elements
    this.list = temp;
}

