public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Check if dayStep is not greater than 6
    if (dayStep > 6) {
        throw new IllegalArgumentException("dayStep cannot be greater than 6");
    }
    // Clamp timeBucket within a reasonable range to avoid overflow or underflow
    timeBucket = Math.max(1, Math.min(timeBucket, Math.pow(10, 18)));

    // Check if timeBucket is a multiple of dayStep
    if (timeBucket % dayStep != 0) {
        throw new IllegalArgumentException("timeBucket must be a multiple of dayStep");
    }

    // Special case for dayStep of 1
    if (dayStep == 1) {
        return (timeBucket / dayStep) * dayStep;
    } else {
        // Apply the dayStep compaction logic
        long start = timeBucket - (timeBucket % dayStep);
        return start + (start % dayStep - timeBucket % dayStep) * (dayStep - 1);
    }
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket < 0 || dayStep <= 0) { // Invalid inputs
        throw new IllegalArgumentException("Input timeBucket and dayStep must be non-negative integers.");
    }

    long year = (long) (timeBucket / (10000 * dayStep));
    long month = (timeBucket % (10000 * dayStep)) / (1000 * dayStep);
    long day = timeBucket % (10000 * dayStep);

    return year * 10000 + month * 1000 + day;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    // Validate input parameters
    if (timeBucket <= 0 || dayStep <= 0) {
        throw new IllegalArgumentException("Invalid time bucket or dayStep value");
    }

    // Calculate the compressed time bucket
    long compressedTimeBucket = timeBucket / dayStep;

    return compressedTimeBucket;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket <= 0 || dayStep <= 0) {
        throw new IllegalArgumentException("Input values must be positive integers.");
    }

    long year = timeBucket / (1000L * 365L * 24L * 60 * 60);
    long month = (timeBucket - year * (1000L * 365L * 24L * 60 * 60)) / (1000L * 30L * 24L * 60 * 60);
    long day = (timeBucket - year * (1000L * 365L * 24L * 60 * 60) - month * (1000L * 30L * 24L * 60 * 60)) / (1000L * 24L * 60 * 60);

    if (dayStep % 366 == 0 || dayStep % 360 == 0) {
        dayStep = dayStep / 366;
    } else if (dayStep % 180 == 0 || dayStep % 168 == 0) {
        dayStep = dayStep / 180;
    } else {
        dayStep = dayStep / 31;
    }

    long startDay = timeBucket - (((day - 1) * dayStep) % 365 + 1) * 1000L * 60 * 60 * 24;
    return startDay;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket <= 0 || dayStep <= 0) {
        throw new IllegalArgumentException("Invalid inputs: timeBucket must be positive and dayStep must be positive.");
    }

    long result = timeBucket;
    for (int i = 1; i < dayStep; i++) {
        result++;
        result = result % 365; // Handle the case where result exceeds 365
    }

    return result;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || index < 0 || index >= str.length() || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        int b = (str.charAt(i) & 0xff);
        if ((b & 0x80) != 0) {
            size++;
            if ((b & 0xE0) != 0) {
                size++;
                if ((b & 0xF0) != 0) {
                    size++;
                }
            } else {
                int last = (b & 0x7E);
                while ((last & 0x40) != 0) {
                    size++;
                    last >>= 1;
                }
            }
        } else {
            size++;
        }
    }

    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len) {
    if (str == null || len <= 0 || index < 0 || len + index > str.length()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        int b = str.charAt(i);
        if ((b & 0x80) == 0) {
            size++;
        } else if ((b & 0xE0) == 0xC0) {
            size += 2;
        } else if ((b & 0xF0) == 0xE0) {
            size += 3;
        } else if ((b & 0xF8) == 0xF0) {
            size += 4;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 sequence found at index " + i);
        }
    }
    return size;
}

public static int computeUTF8Size(CharSequence str, final int index, final int len) {
    int strLength = str.length();
    if (index < 0 || index >= strLength || len < 0 || len > strLength) {
        throw new IllegalArgumentException("Invalid input indices");
    }
    int utf8ByteCount = 0;
    for (int i = index; i < index + len; i++) {
        int codePoint = str.codePointAt(i);
        if (codePoint < 0x80) {
            utf8ByteCount++;
        } else if (codePoint < 0x800) {
            utf8ByteCount += 2;
        } else if (codePoint >= 0xD800 && codePoint < 0xE000) {
            utf8ByteCount += 4;
        } else if (codePoint >= 0x10000) {
            utf8ByteCount += 3;
        }
    }
    return utf8ByteCount;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || index < 0 || len < 0) {
        throw new IllegalArgumentException("'str' cannot be null or 'index' or 'len' cannot be negative.");
    }

    int endIndex = index + len;

    if (endIndex > str.length()) {
        throw new IndexOutOfBoundsException("'index' + 'len' is greater than the length of 'str'");
    }

    // Count the number of bytes used by UTF-8 characters
    int size = 0;
    for (int i = index; i < endIndex; i++) {
        char c = str.charAt(i);
        if (c >= '\u0080' && c <= '\u07FF') {
            size += 2; // Single bytes are 0xxxxxxx
        } else if (c >= '\u0800' && c <= '\uFFFF') {
            size += 3; // Two bytes are 110xxxxx
        } else if (c >= 0x1000' && c <= 0x10FFF) {
            size += 4; // Three bytes are 1110xxxx
        } else if (c >= 0x11000' && c <= 0x11FFFF) {
            size += 5; // Four bytes are 1111xxxx
        } else if (c >= '\uD800' && c <= '\uDFFF' && (i + 1) < endIndex && str.charAt(i + 1) >= '\uDC00' && str.charAt(i + 1) <= '\uDFFF') {
            size += 4; // Two occurrences of the surrogate pair
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 character found at index: " + i);
        }
    }

    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
        int result = 0;
        int pos = index;
        while (pos < index + len && result < Integer.MAX_VALUE) {
            int bite = str.charAt(pos) & 0xFF;
            if (bite >= 0 && bite < 128) {
                pos++;
            } else if (bite >= 128 && bite < 192) {
                int mb = (bite & 0x1F) << 6;
                bite = str.charAt(pos++) & 0xFF;
                mb |= bite & 0x3F;
                result += 2;
            } else if (bite >= 192 && bite < 224) {
                int mb = (bite & 0x3F) << 6;
                bite = str.charAt(pos++) & 0xFF;
                mb |= bite & 0x3F;
                result += 3;
            } else if (bite >= 224 && bite < 240) {
                int mb = (bite & 0x3F) << 6;
                bite = str.charAt(pos++) & 0xFF;
                mb |= bite & 0x3F;
                bite = str.charAt(pos++) & 0xFF;
                mb |= bite & 0x3F;
                result += 4;
            } else {
                throw new IllegalArgumentException("Input is not a valid UTF-8 string");
            }
        }
        return result;
    }

