public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        if (byteLength < 0) {
            throw new IllegalArgumentException("Byte length must be non-negative");
        }
        return super.putBytes(byteLength);
    } else if (byteArrayValue.length == 0) {
        return this;
    } else if (byteArrayValue.length > byteOffset + byteLength) {
        throw new IllegalArgumentException("Array length exceeds the specified offset and byte length");
    }

    super.putBytes(byteArrayValue, byteOffset, byteLength);
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) throws IllegalArgumentException {
    if (byteArrayValue == null) {
        if (byteLength > Integer.MAX_VALUE / Byte.SIZE) {
            throw new IllegalArgumentException("Argument byteArrayValue is null and byteLength is too large");
        }
        byte[] newBytes = new byte[byteLength];
        for (int i = 0; i < byteLength; i++) {
            newBytes[i] = 0;
        }
        this.bytes = newBytes;
        this.offset = byteOffset;
        return this;
    }
    if (byteOffset + byteLength > this.bytes.length) {
        byte[] newBytes = new byte[this.bytes.length + byteLength];
        System.arraycopy(this.bytes, 0, newBytes, 0, this.bytes.length);
        this.bytes = newBytes;
        this.offset += byteLength - this.bytes.length;
    }
    System.arraycopy(byteArrayValue, byteOffset, this.bytes, this.offset, byteLength);
    this.offset += byteLength;
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength) {
    if (byteArrayValue == null) {
        addNullBytes(byteLength);
        return this;
    }

    if (byteOffset < 0 || byteOffset + byteLength > byteArrayValue.length) {
        throw new IllegalArgumentException("Invalid byteOffset and byteLength");
    }

    byte[] newBytes = new byte[length + byteArrayValue.length - byteOffset];
    System.arraycopy(byteArrayValue, byteOffset, newBytes, 0, byteLength);
    this.bytes = newBytes;

    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength) {
    if (byteArrayValue == null) {
        addNullbytes(byteLength);
    } else if (byteArrayValue.length < byteOffset + byteLength) {
        throw new IllegalArgumentException("byteOffset + byteLength exceeds array length");
    }

    System.arraycopy(byteArrayValue, byteOffset, this.bytes, this.cursor, byteLength);
    this.cursor += byteLength;

    return this;
}

