public static LinkedBuffer writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb) {
    if (str == null) throw new IllegalArgumentException("str cannot be null");
    if (lb == null) throw new IllegalArgumentException("lb cannot be null");
    if (session == null) throw new IllegalArgumentException("session cannot be null");

    try {
        for (int i = 0; i < str.length(); i++) {
            final int c = str.charAt(i);
            if (c <= 0x7F) {
                lb.put((byte) c);
            } else if (c <= 0x7FF) {
                lb.put((byte) (0xC0 | ((c >> 6) & 0x1F)));
                lb.put((byte) (0x80 | ((c >> 0) & 0x3F)));
            } else {
                lb.put((byte) (0xE0 | ((c >> 12) & 0xF)));
                lb.put((byte) (0x80 | ((c >> 6) & 0x3F)));
                lb.put((byte) (0x80 | ((c >> 0) & 0x3F)));
            }
        }
    } catch (Exception e) {
        // Handle the exception as needed
        e.printStackTrace();
    }
    return lb;
}

public static void writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb){
    // Check if str is null
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }

    // Check if session is null
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }

    // Check if lb is null
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    try {
        // Get the length of the CharSequence
        int length = str.length();

        // Check if the LinkedBuffer has enough space
        if (lb.hasRemaining(length)) {
            // Write the UTF-8 bytes of the CharSequence to the LinkedBuffer
            lb.putString(str, true);
        } else {
            // Handle the case where there isn't enough space in the LinkedBuffer
            throw new IllegalStateException("LinkedBuffer does not have enough space");
        }
    } catch (Exception e) {
        // Handle any exceptions that may occur during the writing process
        throw new RuntimeException("Failed to write UTF-8 bytes to LinkedBuffer", e);
    }
}

public static void writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || str.length() == 0) {
        return;
    }
    if (session == null) {
        session = new WriteSession();
    }
    if (lb == null) {
        lb = new LinkedBuffer();
    }
    try {
        byte[] utfBytes = str.toString().getBytes("UTF-8");
        lb.writeUTF8(utfBytes);
    } catch (UnsupportedEncodingException e) {
        throw new RuntimeException("UTF-8 encoding not supported", e);
    }
}

public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) throws IOException {
    CharsetEncoder encoder = StandardCharsets.UTF_8.newEncoder();
    encoder.onMalformedInput(CodingErrorAction.REPORT);
    encoder.onUnmappableCharacter(CodingErrorAction.REPORT);

    Writer writer = new BufferedWriter(new OutputStreamWriter(lb, encoder));

    try {
        writer.write(str);
        writer.flush();
    } catch (IOException e) {
        throw new IOException("Failed to write string to buffer", e);
    } finally {
        if (writer != null) {
            writer.close();
        }
    }

    return lb;
}

static LinkedBuffer writeUTF8(CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || lb == null 
            || session == null || session.isClosed() 
            || !session.canWrite()) {
        throw new IllegalArgumentException("Invalid input parameters.");
    }

    try {
        lb.writeUTF8(str, 0, str.length());
    } catch (IOException e) {
        e.printStackTrace();
        throw new RuntimeException("Error writing UTF-8 bytes to LinkedBuffer.", e);
    }

    return lb;
}

