public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    // Check if the URI is null
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }

    // Extract the path segment
    String path;
    if (!u.isAbsolute() || u.getRawSchemeSpecificPart() == null || u.getRawSchemeSpecificPart().isEmpty()) {
        path = u.getSchemeSpecificPart();
    } else {
        path = u.getRawSchemeSpecificPart().split(" ")[0]; // Split the first segment based on ' '
    }

    // Strip any leading '/' or '&' characters
    path = path.replaceAll("^[/&]+", ""); // Remove leading characters
    path = path.replaceAll("[^/&]+(?=[/&]+)", ""); // Remove segments until at the end

    // Split the path segment by '/'
    List<String> segments = splitBySlash(path, decode);

    // Populate the list of path segments with PathSegmentImpl
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    for (String segment : segments) {
        pathSegments.add(new PathSegmentImpl(segment));
    }

    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    if (u == null) {
        throw new NullPointerException("URI cannot be null");
    }

    String path = decode ? u.getPath() : u.toASCIIString().substring(u.getPath().indexOf('/') + 1);
    for (String segment : path.split("/")) {
        if (!segment.isEmpty()) {
            pathSegments.add(new PathSegmentImpl(segment));
        }
    }

    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        if (u == null) {
            throw new IllegalArgumentException("URI cannot be null");
        }

        Path path = Paths.get(decode ? u.getRawPath() : u.getPath());
        List<PathSegmentImpl> segments = new ArrayList<>();

        for (PathSegmentImpl segment : pathSegments(path)) {
            if (decode && segment.getType() != PathSegment.Type.REF) {
                segments.add(new PathSegmentImpl(segment.getPath(), segment.getType()));
            } else {
                segments.add(segment);
            }
        }

        return segments;
    }

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = (decode ? u.getPath().substring(1) : u.getPath()).replace('%3A', ':').replace('%2F', '/');

    int i = 0;
    while (i < path.length()) {
        char c = path.charAt(i);
        if (c == '%') {
            if (i + 2 >= path.length()) {
                throw new IllegalArgumentException("Invalid URI path segment");
            }
            String hexCode = path.substring(i + 1, i + 3);
            byte[] decodedBytes = java.net.URLDecoder.decode(hexCode, StandardCharsets.UTF_8);
            String decodedString = new String(decodedBytes, StandardCharsets.UTF_8);
            pathSegments.add(new PathSegmentImpl(decodedString));
            i += 3;
        } else if (c == '/') {
            pathSegments.add(new PathSegmentImpl(""));
            i++;
        } else {
            pathSegments.add(new PathSegmentImpl(String.valueOf(c)));
            i++;
        }
    }
    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    try {
        // Extract and decode the path component
        String path = u.getPath();
        if (!decode) {
            path = path.substring(1);
        }
        return List.of(new PathSegmentImpl(path));
    } catch (Exception e) {
        // Handle exceptions gracefully
        throw new RuntimeException("Failed to decode path component", e);
    }
}

