    if (box == null || !box.getBounds2D().isMutable()) {
        throw new IllegalArgumentException("Invalid box or immutable box's bounds.");
    }

    double leftX = box.getX();
    double rightX = box.getX() + box.getWidth();
    Box2D leftBox = new Box2D(leftX, box.getY(), box.getWidth() / 2, box.getHeight());
    Box2D rightBox = new Box2D(rightX, box.getY(), box.getWidth() / 2, box.getHeight());

    return Pair.of(leftBox, rightBox);
}

