    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }
    float width = box.getWidth();
    float center = box.getMinX() + width / 2f;
    Bounds2D lower = new Bounds2D(box.getMinX(), box.getMinY(), center - box.getWidth() / 2f, box.getHeight());
    Bounds2D upper = new Bounds2D(center + box.getWidth() / 2f, box.getMinY(), box.getMaxX(), box.getHeight());
    return new Pair<>(new Box2D(lower), new Box2D(upper));
}

