    Box2D lowerBox = new Box2D(box.getMin().getX(), box.getMin().getY(), midpoint, box.getMax().getY());
    Box2D upperBox = new Box2D(midpoint, box.getMin().getY(), box.getMax().getX(), box.getMax().getY());

