    if (desiredCapacity > 1000) {
        for (int i = 1; i < Integer.MAX_VALUE; i++) {
            if (isPrime(i)) {
                return (int) ((11.0 + 1.0 / 12.0 * i) * Math.sqrt(desiredCapacity));
            }
        }
