    int trailingIndex = str.length() - 1;
    while (trailingIndex >= 0 && Character.isWhitespace(str.charAt(trailingIndex))) {
        trailingIndex--;
    }

    if (trailingIndex < str.length() - 1) {
        return str.substring(0, trailingIndex + 1);
    } else {
        return str; // Return the original string if no trailing whitespace was found
    }
}

