private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    if (array instanceof byte[]) {
        byte[] newArray = (byte[]) new byte[((byte[]) array).length + 1];
        System.arraycopy(array, 0, newArray, 0, array.length);
        return newArray;
    } else if (array instanceof short[]) {
        short[] newArray = (short[]) new short[((short[]) array).length + 1];
        System.arraycopy(array, 0, newArray, 0, array.length);
        return newArray;
    } else if (array instanceof int[]) {
        int[] newArray = (int[]) new int[((int[]) array).length + 1];
        System.arraycopy(array, 0, newArray, 0, array.length);
        return newArray;
    } else if (array instanceof long[]) {
        long[] newArray = (long[]) new long[((long[]) array).length + 1];
        System.arraycopy(array, 0, newArray, 0, array.length);
        return newArray;
    } else if (array instanceof float[]) {
        float[] newArray = (float[]) new float[((float[]) array).length + 1];
        System.arraycopy(array, 0, newArray, 0, array.length);
        return newArray;
    } else if (array instanceof double[]) {
        double[] newArray = (double[]) new double[((double[]) array).length + 1];
        System.arraycopy(array, 0, newArray, 0, array.length);
        return newArray;
    } else if (array instanceof char[]) {
        char[] newArray = new char[((char[]) array).length + 1];
        System.arraycopy(array, 0, newArray, 0, array.length);
        return newArray;
    } else if (array instanceof boolean[]) {
        boolean[] newArray = new boolean[((boolean[]) array).length + 1];
        System.arraycopy(array, 0, newArray, 0, array.length);
        return newArray;
    } else {
        if (newArrayComponentType == null) {
            throw new IllegalArgumentException(" newArrayComponentType cannot be null when the array is not of type byte[], short[], int[], long[], float[], double[], char[], or boolean[].");
        }
        Object newArray = newArrayComponentType.getDeclaredConstructor().newInstance();
        for (int i = 0; i < array.length; i++) {
