}

private int computeBinaryLog(int n) {
    // Check if n is positive
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    // Start with an initial count of log base 2
    int count = 0;

    // Count the highest power of 2 less than or equal to n
    while ((1 << count) <= n) {
        count++;
    }

    // Return the calculated result
    return count;
}

private static int computeBinaryLog(int n) {
    if (n < 1) {
        throw new IllegalArgumentException("Input must be greater than or equal to 1");
