public static byte convertHexDigit(byte b) {
    if (b < '0' || (b > '9' && b < 'a') || (b > 'F' && b < 'A')) {
        throw new IllegalArgumentException("Invalid input: " + b);
    }
    b &= 0x0F; // Trim off the high order bits
    if (b >= 'A') {
        b -= 0x37; // Convert from 'A' to 'F'
    } else {
        b -= 0x30; // Convert from '0' to '9'
    }
    return b;
}

public static byte convertHexDigit(byte b) {
    if (b > 57) {                               // '9' is ASCII 57
        b -= 7;                                  // subtract 7 to convert 'A'-'F' to '0'-15
    } else if (b > 64) {                        // 'F' is ASCII 64
        b -= 55;                                  // subtract 55 to convert 'A'-'F' to '0'-15
    }
    return (byte) b;
}

public static byte convertHexDigit(byte b) {
    if (b >= '0' && b <= '9') {
        return (byte) (b - '0');
    } else if (b >= 'a' && b <= 'f') {
        return (byte) (10 + (b - 'a'));
    } else if (b >= 'A' && b <= 'F') {
        return (byte) (10 + (b - 'A'));
    } else {
        throw new IllegalArgumentException("Invalid hexadecimal digit");
    }
}

public static byte convertHexDigit(byte b) {
    if (b < '0' || (b > '9' && b < 'A') || (b > 'F')) {
        throw new IllegalArgumentException("Invalid byte: " + b);
    }
    if (b >= '0' && b <= '9') {
        return (byte) (b - '0');
    } else {
        return (byte) (b - 'A' + 10);
    }
}

public static byte convertHexDigit(byte b) {
    byte result;
    switch (b) {
        case '0':
        case '1':
        case '2':
        case '3':
        case '4':
        case '5':
        case '6':
        case '7':
        case '8':
        case '9':
            result = b - '0';
            break;
        case 'a':
        case 'b':
        case 'c':
        case 'd':
        case 'e':
        case 'f':
            result = b - 'a' + 10;
            break;
        case 'A':
        case 'B':
        case 'C':
        case 'D':
        case 'E':
        case 'F':
            result = b - 'A' + 10;
            break;
        default:
            throw new IllegalArgumentException("Invalid Hex Digit");
    }
    return result & 0xFF;
}

