protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
        if (tour == null || graph == null) {
            throw new IllegalArgumentException("Input graph or tour cannot be null.");
        }

        if (tour.isEmpty()) {
            return new GraphPath<>();
        }

        GraphPath<V,E> path = new GraphPath<>();
        V currentVertex = graph.findNodeById(tour.iterator().next().source());
        path.addVertex(currentVertex);

        for (E edge : tour) {
            V nextVertex = graph.findNodeById(edge.target());
            path.addVertex(nextVertex);
            path.addEdge(edge);
            currentVertex = nextVertex;
        }

        return path;
    }

