    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Parameter cannot be null");
    }

    GraphPath<V, E> path = new DirectedSimpleGraph<>(graph.topology());

    for (E edge : tour) {
        V source = graph.source(edge);
        V target = graph.target(edge);

        path.addEdge(source, target);
    }

    return path;
}

protected <V, E extends DirectedEdge<V>> GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        if (tour == null || graph == null) {
            throw new IllegalArgumentException("Input graphs cannot be null");
        }

        Map<E, GraphPathNode<V, E>> nodeMap = new HashMap<>();
        for (E edge : tour) {
            GraphNode<V, E> startNode = getNode(nodeMap, graph.getNode(edge.getSource()));
            GraphNode<V, E> endNode = getNode(nodeMap, graph.getNode(edge.getDestination()));

            if (startNode == null || endNode == null) {
                throw new IllegalArgumentException("Node found in tour is not present in the graph");
            }

            GraphPath<E> path = new GraphPath<>();
            path.add(startNode);
            E previousEdge = edge;
            while (!startNode.equals(endNode)) {
                Set<Edge<V, E>> adjacency = graph.getAdjacency(startNode);
                Edge<V, E> nextEdge = adjacency.stream()
                        .filter(edge -> !edge.equals(previousEdge))
                        .findFirst()
                        .orElse(null);
                if (nextEdge == null) {
                    throw new IllegalStateException("No edge to continue the path");
                }
                path.add(graph.getNode(nextEdge.getDestination()));
                previousEdge = nextEdge;
            }
            path.add(endNode);
            nodeMap.put(edge, path);
        }

        return nodeMap.values().stream().findFirst().orElse(null);
    }

private GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null || tour.isEmpty() || graph.isDirected()) {
        throw new IllegalArgumentException("Invalid arguments: tour and graph cannot be null and tour cannot be empty, and graph should not be directed.");
    }

    List<V> nodes = new ArrayList<>();
    Map<V,Integer> nodeIndices = new HashMap<>();

    // Add nodes to the graph and a corresponding index map
    for (E edge : tour) {
        V u = graph.getEdgeSource(edge);
        V v = graph.getEdgeTarget(edge);

        if (!nodes.contains(u)) {
            nodes.add(u);
            nodeIndices.put(u, nodes.indexOf(u));
        }

        if (!nodes.contains(v)) {
            nodes.add(v);
            nodeIndices.put(v, nodes.indexOf(v));
        }
    }

    List<EdgeDescriptor> edgeDescriptors = new ArrayList<>();

    // Collect edge descriptors from the tour
    for (E edge : tour) {
        int sourceIndex = nodeIndices.get(graph.getEdgeSource(edge));
        int targetIndex = nodeIndices.get(graph.getEdgeTarget(edge));
        edgeDescriptors.add(new EdgeDescriptor(sourceIndex, targetIndex));
    }

    // Create a graph path from the edge descriptors
    return new GraphPath<>(nodes, edgeDescriptors);
}

