private String unescapeId(String input) throws IllegalArgumentException {
    // Ensure input is not null
    if (input == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }

    StringBuilder res = new StringBuilder();
    boolean isQuoted = false;
    boolean isEscaping = false;

    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);

        if (isEscaping) {
            // We've escaped a character, so remove the escape
            res.append(c); 
            isEscaping = false;
        } else if (c == '\\') {
            // We've encountered an escape character
            isEscaping = true;
        } else if (c == '"') {
            // We've encountered a quote
            if (!isQuoted) {
                // If not within quotes, start quoting and reset isEscaping flag
                isQuoted = true;
                res.append('\\'); // Escape the quote
            } else {
                // If within quotes, end quoting
                isQuoted = false;
                res.append('\\'); // Escape the quote
            }
        } else {
            // Not an escape character; append as is
            res.append(c);
        }
    }

    return res.toString();
}

