    List<Integer> relocatedVertices = new ArrayList<>();

    for (int label : currentBucket) {
        labels.set(label, 0);
        relocatedVertices.add(label);
        bucketsByLabel.remove(label);
        while (bucketsByLabel.size() > 0 && bucketsByLabel.get(0).isEmpty()) {
            idleBuckets.add(bucketsByLabel.remove(0));
        }
        // Place the copied labels back to the buckets
        for (Integer bucketId : idleBuckets) {
            if (bucketId < minLabel) {
                bucketsByLabel.add(bucketId, new HashSet<>(relocatedVertices));
                return;
            }
        }
    }
}

