public boolean unlink(ListNodeImpl<E> node) {
    // Check if the node is null or the list is empty
    if (node == null || this.head == null) {
        return false; // The node does not exist or the list is empty
    }

    // Check if the node to be removed is the head of the list
    if (node == this.head) {
        this.head = node.next; // Update the head to the next node
    } else {
        ListNodeImpl<E> current = this.head;
        while (current.next != null && current.next != node) {
            current = current.next; // Traverse to the node before the node to be removed
        }
        if (current.next != null) {
            current.next = current.next.next; // Remove the node from the list
        } else {
            return false; // The node to be removed was not found
        }
    }
    return true; // Successfully unlinked the node
}

