private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list.isEmpty()) {
        return;
    }

    ListNode<E> currentNode = list.getFirst();
    while (currentNode != null) {
        ListNode<E> nextNode = currentNode.getNext();
        // Remove the node from the original list
        list.removeListNode(currentNode);
        // Add the node to this list
        addListNode(currentNode);
        currentNode = nextNode;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Safety check: If the input list is null, throw an IllegalArgumentException
    if (list == null) {
        throw new IllegalArgumentException("Input list cannot be null");
    }

    // Create a backup of the head of list
    ListNodeImpl<E> head = list.getHead();

    // Split the input list
    DoublyLinkedList<E> leftList = new DoublyLinkedList<>();
    DoublyLinkedList<E> rightList = new DoublyLinkedList<>();

    leftList.setHead(head); // Head of leftList is now the Same as head of list

    while (list.hasNext()) {
        ListNodeImpl<E> currentNode = list.next();
        // Navigates to the end of the list
        currentNode = head;
        do {
            if (currentNode.next() == null) {
                currentNode.next = rightList.getHead();
                rightList.setHead(currentNode);
                break;
            }
            currentNode = currentNode.next();
        } while (true);

        list.removeListNode(currentNode); // Removes the smallest node from the input list
    }

    // Updates the head of list to the start of the first element of rightList
    head.setNext(rightList.getHead());

    // Updates the head pointer of leftList (now empty)
    leftList.setHead(null);
}

private synchronized void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new IllegalArgumentException("list cannot be null");
    }

    if (this.head != null) {
        while (this.head.next != null) {
            head.next.prev = null;
            head = head.next;
        }
        this.head.next = list.head;
        list.head.prev = this.head;
    }

    if (this.tail != null) {
        while (this.tail.prev != null) {
            tail.prev.next = null;
            tail = tail.prev;
        }
        tail.prev = list.tail;
        list.tail.next = tail;
    }
}

