        throw new IllegalArgumentException("Invalid table or row index");
    }

    int viewStart = pane.getVisibleRect().y;
    int viewEnd = viewStart + pane.getViewport().getHeight();

    if (row < viewStart || row >= viewEnd) {
        pane.scrollRectToVisible(new Rectangle(table.getCellRect(row, 0)));
    } else {
        int viewY =.table.getRowAt(row).getLocation().y;
        int boundY = viewY + pane.getRowHeight(row);
