    if (vertices == null || graph == null || graph.vertexSet().size() < 0 
        || graph.vertexSet().size() != vertices.size()) {
        throw new IllegalArgumentException("Vertices must be a subset of the graph's vertices and size must be non-negative");
    }

    for (V v : vertices) {
        for (V u : vertices) {
            if (u.equals(v)) continue; // same vertex
            if (!graph.containsEdge(v, u)) return false; // no edge between u and v
        }
    }

    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph,Set<V> vertices) {
    for (V v : vertices) {
        if (graph.degree(v) < vertices.size() - 1) {
            return false;
        }
        for (V w : vertices) {
            if (v.equals(w) || !graph.hasEdge(v, w)) {
                continue;
            }
            for (V x : vertices) {
                if (x.equals(v) || x.equals(w) || !graph.hasEdge(w, x)) {
                    return false;
                }
                if (!graph.hasEdge(v, x)) {
                    return false;
                }
            }
        }
    }
    return true;
}

