public static String applyRelativePath(String path, String relativePath) {
    // Check if the path and relative path are not null
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path cannot be null");
    }

    // Split the path into various segments
    String[] pathSegments = path.split("/");
    String[] relativePathSegments = relativePath.split("/");

    // Process the relative path
    StringBuilder newPath = new StringBuilder();
    for (String segment : relativePathSegments) {
        if ("..".equals(segment)) {
            if (newPath.length() > 0) {
                newPath.deleteCharAt(newPath.length() - 1);
            }
        } else if (segment.equals(".")) {
            // Skip current directory
            continue;
        } else {
            newPath.append('/').append(segment);
        }
    }

    // Combine the original path segments with the processed relative path
    for (String segment : pathSegments) {
        newPath.append('/').append(segment);
    }

    // Return the full file path
    return newPath.toString();
}

